import json
from pathlib import Path
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

app = FastAPI()
app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:5173", "https://vt-course-planner.vercel.app"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Full catalog, generated by scrape_catalog.py
COURSES_FILE = Path(__file__).parent / "courses.json"
courses = json.loads(COURSES_FILE.read_text()) if COURSES_FILE.exists() else []


@app.get("/")
def home():
    return {"message": "VT Course Planner backend is running", "courses": len(courses)}


@app.get("/courses")
def get_courses():
    return courses
